create function public.record_handover(t uuid,note text) returns void language plpgsql security definer set search_path=public as $$ begin if not public.has_tenant(t,true,true) or length(note)>2000 or length(note)=0 then raise exception 'Forbidden';end if;insert into audit(tenant_id,entity_id,action,actor) values(t,gen_random_uuid(),'Shift handover: '||note,auth.uid()::text);end $$;
revoke all on function record_handover(uuid,text) from public;grant execute on function record_handover(uuid,text) to authenticated;
create function public.ingest_gps(payload jsonb) returns boolean language plpgsql security definer set search_path=public as $$ declare v vehicles;inserted integer;begin
select * into v from vehicles where id=(payload->>'vehicle_id')::uuid and tenant_id=(payload->>'tenant_id')::uuid for update;if not found then raise exception 'Vehicle unavailable';end if;
if v.provider<>payload->>'provider' and not(v.simulated and payload->>'provider'='Simulator') then raise exception 'Provider mismatch';end if;
insert into tracking_events(tenant_id,vehicle_id,provider,event_id,lat,lng,speed,recorded_at) values(v.tenant_id,v.id,payload->>'provider',payload->>'event_id',(payload->>'lat')::float8,(payload->>'lng')::float8,(payload->>'speed')::float8,(payload->>'recorded_at')::timestamptz) on conflict do nothing;get diagnostics inserted=row_count;if inserted=0 or (v.gps_at is not null and v.gps_at>=(payload->>'recorded_at')::timestamptz) then return false;end if;
update vehicles set lat=(payload->>'lat')::float8,lng=(payload->>'lng')::float8,speed=(payload->>'speed')::float8,gps_at=(payload->>'recorded_at')::timestamptz,simulated=(payload->>'provider'='Simulator'),location='GPS '||(payload->>'lat')||', '||(payload->>'lng') where id=v.id;return true;end $$;
create function public.record_eta(t uuid,j uuid,new_eta timestamptz,route_provider text) returns void language plpgsql security definer set search_path=public as $$ begin update jobs set eta=new_eta,eta_approved=false where tenant_id=t and id=j;if not found then raise exception 'Job unavailable';end if;insert into eta_history(tenant_id,job_id,eta,provider) values(t,j,new_eta,route_provider);end $$;
create function public.monitor_fleet() returns integer language plpgsql security definer set search_path=public as $$ declare inserted integer;total integer:=0;begin
insert into alerts(tenant_id,vehicle_id,severity,title,detail) select tenant_id,id,'warning','Stale GPS signal','No confirmed GPS received for over 30 minutes' from vehicles where gps_at is null or gps_at<now()-interval '30 minutes' on conflict do nothing;get diagnostics inserted=row_count;total:=total+inserted;
insert into alerts(tenant_id,vehicle_id,severity,title,detail) select tenant_id,vehicle_id,'critical','Delivery at risk',reference||': ETA exceeds delivery window by over 30 minutes' from jobs where status in('Loaded','In Transit','At Delivery') and eta>scheduled_at+interval '30 minutes' on conflict do nothing;get diagnostics inserted=row_count;total:=total+inserted;
insert into alerts(tenant_id,vehicle_id,severity,title,detail) select v.tenant_id,v.id,'warning','Unexpected stop','Zero-speed GPS samples for 20 minutes in transit. Controller confirmation required.' from vehicles v where v.gps_at>now()-interval '10 minutes' and exists(select 1 from jobs j where j.vehicle_id=v.id and j.tenant_id=v.tenant_id and j.status='In Transit') and (select count(*) from tracking_events e where e.vehicle_id=v.id and e.tenant_id=v.tenant_id and e.recorded_at>now()-interval '25 minutes')>=3 and not exists(select 1 from tracking_events e where e.vehicle_id=v.id and e.tenant_id=v.tenant_id and e.recorded_at>now()-interval '25 minutes' and e.speed>3) and exists(select 1 from tracking_events e where e.vehicle_id=v.id and e.tenant_id=v.tenant_id and e.recorded_at between now()-interval '25 minutes' and now()-interval '20 minutes') on conflict do nothing;get diagnostics inserted=row_count;total:=total+inserted;
insert into alerts(tenant_id,vehicle_id,severity,title,detail) select tenant_id,vehicle_id,'warning','Document expiring',name||' expires within 30 days' from documents where vehicle_id is not null and expires_at<now()+interval '30 days' on conflict do nothing;get diagnostics inserted=row_count;return total+inserted;end $$;
revoke all on function ingest_gps(jsonb),record_eta(uuid,uuid,timestamptz,text),monitor_fleet() from public,authenticated;grant execute on function ingest_gps(jsonb),record_eta(uuid,uuid,timestamptz,text),monitor_fleet() to service_role;
create index tracking_vehicle_time on tracking_events(tenant_id,vehicle_id,recorded_at desc);
create index jobs_tenant_status on jobs(tenant_id,status);
create index documents_expiry on documents(tenant_id,expires_at);
create index audit_tenant_time on audit(tenant_id,created_at desc);
